@startuml

class Bettor {
  + bettorId : int
  + name : string
  + contactInfo : string
}

class Race {
  + raceId : int
  + raceName : string
  + startTime : datetime
}

class Runner {
  + runnerId : int
  + horseName : string
}

class Jockey {
  + jockeyId : int
  + name : string
}

class Bet {
  + betId : int
  + amount : double
  + odds : double
}

class Bookmaker {
  + bookmakerId : int
  + name : string
}

Bettor "1" -- "0..*" Bet : places
Bookmaker "1" -- "0..*" Bet : accepts
Race "1" *-- "1..*" Runner
Runner "1" *-- "1" Jockey
Race "1" -- "0..1" Runner : winner
Bet "0..*" -- "1" Race
Bet "0..*" -- "1" Runner
Bookmaker "1" -- "0..*" Bettor : manages

@enduml

